-- =====================================================================
--  WMS - Demo seed data (multi-provider)
--
--  Run AFTER schema.sql and upgrade_multi_provider.sql.
--
--  Platform owner : admin  / Admin@123      (Super Admin, global scope)
--  Provider A     : mbaruku / Admin@123     (Mbaruku WiFi)
--  Provider B     : fastnet / Admin@123     (FastNet WiFi)
--  Customer portal: 0754000001 / Customer@123
--
--  Two providers exist so you can prove the isolation: sign in as one
--  and you must never see the other's customers, vouchers or routers.
--  All network data below is SIMULATED and flagged source='demo'.
-- =====================================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- The upgrade created PRV-0001 as 'Default Wi-Fi Provider'; the demo
-- data renames it and adds a second tenant beside it.
ON DUPLICATE KEY UPDATE `business_name`=VALUES(`business_name`), `business_type`=VALUES(`business_type`),
  `owner_name`=VALUES(`owner_name`), `phone`=VALUES(`phone`), `email`=VALUES(`email`), `city`=VALUES(`city`),
  `description`=VALUES(`description`), `status`=VALUES(`status`);

-- Platform owner keeps provider_id NULL; every other account belongs to one provider.
ON DUPLICATE KEY UPDATE `full_name`=VALUES(`full_name`), `provider_id`=VALUES(`provider_id`), `role_id`=VALUES(`role_id`);

ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `provider_id`=VALUES(`provider_id`);

ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `provider_id`=VALUES(`provider_id`);

ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `provider_id`=VALUES(`provider_id`);

ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `provider_id`=VALUES(`provider_id`);

ON DUPLICATE KEY UPDATE `full_name`=VALUES(`full_name`), `provider_id`=VALUES(`provider_id`);

ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `provider_id`=VALUES(`provider_id`);

ON DUPLICATE KEY UPDATE `code`=VALUES(`code`), `provider_id`=VALUES(`provider_id`);

ON DUPLICATE KEY UPDATE `transaction_ref`=VALUES(`transaction_ref`), `provider_id`=VALUES(`provider_id`);

ON DUPLICATE KEY UPDATE `status`=VALUES(`status`), `provider_id`=VALUES(`provider_id`);

ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `provider_id`=VALUES(`provider_id`);

ON DUPLICATE KEY UPDATE `status`=VALUES(`status`), `provider_id`=VALUES(`provider_id`);

ON DUPLICATE KEY UPDATE `total_bytes`=VALUES(`total_bytes`), `provider_id`=VALUES(`provider_id`);

ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `provider_id`=VALUES(`provider_id`);

ON DUPLICATE KEY UPDATE `action`=VALUES(`action`);

-- provider_id 0 = platform default; a real id = that provider's own value.
ON DUPLICATE KEY UPDATE `setting_value`=VALUES(`setting_value`);

SET FOREIGN_KEY_CHECKS = 1;

